import sailpoint.object.ManagedAttribute;
import java.util.List;
import java.util.ArrayList;
import java.util.Set;
import java.util.HashSet;
import java.util.Collections;

String SOURCE_ID = "6659e1f4005c400e8ce339362afef7c6";

String identityAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "identityAttribute");
String entitlementAccAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "entitlementAccountAttribute");
String entitlementParentAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "entitlementParentAttribute");
String entitlementDisplayAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "entitlementDisplayAttribute");
String hierarchySep = idn.getSourceAttributeBySourceId(SOURCE_ID, "hierarchySeparator");

if (identityAttr == null || entitlementAccAttr == null || entitlementDisplayAttr == null) {
    return "DEBUG: missing source attrs | identityAttr=" + identityAttr + " | entitlementAccAttr=" + entitlementAccAttr + " | entitlementDisplayAttr=" + entitlementDisplayAttr;
}

String entitlementValue = null;
if (identity != null) {
    Object val = identity.getAttribute(identityAttr);
    if (val != null) {
        entitlementValue = val.toString();
    }
}

String entitlementValueOut = "EMPTY";
if (entitlementValue == null) {
    entitlementValueOut = "NULL";
}
if (entitlementValue == null || entitlementValue.trim().isEmpty()) {
    return "DEBUG: identityAttr empty | identityAttr=" + identityAttr + " | entitlementValue=" + entitlementValueOut;
}

List path = new ArrayList();
Set visited = new HashSet();
String current = entitlementValue;
int maxDepth = 20;
String lastAttrsStr = "-";
boolean lastDetailsNull = false;
boolean lastAttrsNull = false;

while (current != null && !current.trim().isEmpty() && !visited.contains(current) && path.size() < maxDepth) {
    visited.add(current);

    sailpoint.rule.ManagedAttributeDetails details = idn.getManagedAttributeDetails(
        SOURCE_ID, entitlementAccAttr, current, null
    );
    if (details == null) {
        lastDetailsNull = true;
        break;
    }

    java.util.Map attrs = details.getAttributes();
    if (attrs == null) {
        lastAttrsNull = true;
        break;
    }

    String name = details.getName();
    String pathName = current;
    if (name != null) {
        pathName = name;
    }
    path.add(pathName);

    String nameOut = "NULL";
    if (name != null) {
        nameOut = name;
    }
    Object parentVal = attrs.get(entitlementParentAttr);
    if (parentVal == null || parentVal.toString().trim().isEmpty()) {
        lastAttrsStr = "" + attrs.keySet();
        return "DEBUG: path=" + path.size() + " | current=" + current + " | displayAttrName=" + entitlementDisplayAttr + " | parentAttrName=" + entitlementParentAttr + " | attrKeys=" + lastAttrsStr + " | DISPLAY=" + nameOut + " | PARENT-NULL | entitlementValue=" + entitlementValue;
    }
    current = parentVal.toString();
}

if (path.isEmpty()) {
    String detailsNullFlag = "NO-PATH";
    if (lastDetailsNull) {
        detailsNullFlag = "DETAILS-NULL";
    } else if (lastAttrsNull) {
        detailsNullFlag = "ATTRS-NULL";
    }
    return "DEBUG: path empty | current=" + current + " | displayAttrName=" + entitlementDisplayAttr + " | parentAttrName=" + entitlementParentAttr + " | attrKeys=" + lastAttrsStr + " | " + detailsNullFlag + " | entitlementValue=" + entitlementValue;
}

Collections.reverse(path);
StringBuilder result = new StringBuilder();
for (int i = 0; i < path.size(); i++) {
    if (i > 0 && hierarchySep != null) {
        result.append(hierarchySep);
    }
    result.append(path.get(i));
}
return result.toString();
